// === Tab: Sketch ===
// By Roni Kaufman
// Inspired by Sol LeWitt's "Squiggly Brushstrokes"

var particles = [];
var n = 120;
var colors;
var squiggliness;
var maxSize = 7;
var minSize = 1;
var size;
var t;
var interval;
var minHue = 0;
var margin = 80;

function setup() {
  createCanvas(600, 600);
  colorMode(HSB, 1);
  noStroke();

  background(0.6, 0.75, 0.25);
	size = maxSize;
	squiggliness = random(1/300, 1/1000);
	minHue = random(0.95, 1.03);
	if (random(1) < 0.5) {
		minHue = (minHue + 0.5);
	}
	minHue %= 1;

  //updateParticles();
  interval = setInterval(updateParticles, 600);
}

function draw() {
  for (let p of particles) {
    p.draw();
    p.move();
  }
}

function updateParticles() {
	t = map(size, maxSize, minSize, 0, 1);
  particles = [];
  for (let i = 0; i < n; i++) {
    let x_ = random(margin, width - margin);
    let y_ = random(margin, height - margin);
    let c_ = interpolateColor(t);
    particles.push(new Particle(x_, y_, size, c_));
  }
	size -= 0.25;
	if (size <= minSize) {
		clearInterval(interval);
		// noLoop() removed for animation
	}
}

function interpolateColor(t) {
	let hue = (t/5 + minHue)%1;
	if (random(1) < 0.2) {
		hue = (hue+0.5)%1;
	}
	let sat = 1 + random(-0.05, 0);
	let val = 1 + random(-0.05, 0);
	return color(hue, sat, val);
}

function Particle(x_, y_, s_, c_) {
  this.x = x_;
  this.y = y_;
  this.size = s_;
  this.c = c_;

  this.dist = 1;

  this.move = function() {
    let theta = noise(this.x * squiggliness, this.y * squiggliness)*PI*4;
    let v = p5.Vector.fromAngle(theta, this.dist);
    this.x += v.x;
    this.y += v.y;

		if (this.x < margin || this.x > width - margin || this.y < margin || this.y > height - margin) {
			this.dist *= 0.97;
		}
  }

  this.draw = function() {
    fill(this.c);
    circle(this.x, this.y, this.size);
  }
}
